        temperature = params.get("temperature", 0.7)
        reasoning_effort = params.get("reasoning_effort")
        # passthrough: top_p, top_k, presence_penalty, frequency_penalty, max_tokens, etc.
        HANDLED_KEYS = {"temperature", "reasoning_effort"}
